          "hint": "Multiply length by width.",
          "subject": "math",
          "chapter": "geometry",
          "topic": "Area of a Rectangle",
          "conceptId": "math_geometry_area_of_a_rectangle",
          "skillId": "math_geometry",
          "subskillId": "math_geometry_q1"
